// ⚙️ Configuración del negocio de la demo. Es el ÚNICO nodo que hay que
// editar para adaptar el bot a otro negocio (servicios, horario, IDs).
return [{
  json: {
    negocio: 'Clínica Dental Sonrisa · DEMO',
    direccion: 'Calle Ficticia 123, Bogotá (dirección de demostración)',
    calendar_id: 'PEGAR_ID_DEL_CALENDARIO@group.calendar.google.com',
    sheet_id: 'PEGAR_ID_DE_LA_HOJA',
    hoja: 'Citas',
    alex_chat_id: 'PEGAR_TU_CHAT_ID_DE_TELEGRAM',
    zona: 'America/Bogota',
    offset: '-05:00',
    // Duración en minutos de cada servicio.
    servicios: [
      { id: 'valoracion', nombre: 'Valoración', min: 30 },
      { id: 'limpieza', nombre: 'Limpieza dental', min: 45 },
      { id: 'blanqueamiento', nombre: 'Blanqueamiento', min: 60 },
      { id: 'ortodoncia', nombre: 'Control de ortodoncia', min: 30 },
    ],
    // Horario por día de la semana (0 = domingo … 6 = sábado).
    horario: {
      1: [['08:00', '12:00'], ['14:00', '18:00']],
      2: [['08:00', '12:00'], ['14:00', '18:00']],
      3: [['08:00', '12:00'], ['14:00', '18:00']],
      4: [['08:00', '12:00'], ['14:00', '18:00']],
      5: [['08:00', '12:00'], ['14:00', '18:00']],
      6: [['08:00', '12:00']],
    },
    paso_min: 30,          // cada cuánto se ofrece un turno
    dias_adelante: 7,      // hasta cuántos días se puede agendar
    anticipacion_min: 60,  // mínimo de minutos entre "ahora" y la cita
  },
}];

// Traduce la actualización de Telegram a un formato común, igual para
// cualquier canal: { canal, chat_id, usuario_id, nombre, texto, boton }.
// El motor de citas solo conoce este formato, nunca el de Telegram.
const u = $('Telegram (entrada)').first().json.body || {};
const cfg = $('Configuracion').first().json;
const e = { canal: 'telegram', ignorar: false, texto: '', boton: '', callback_id: '' };

if (u.callback_query) {
  const q = u.callback_query;
  e.chat_id = String((q.message && q.message.chat && q.message.chat.id) || q.from.id);
  e.usuario_id = String(q.from.id);
  e.nombre = [q.from.first_name, q.from.last_name].filter(Boolean).join(' ');
  e.boton = String(q.data || '');
  e.callback_id = String(q.id);
} else if (u.message && typeof u.message.text === 'string') {
  const m = u.message;
  e.chat_id = String(m.chat.id);
  e.usuario_id = String(m.from ? m.from.id : m.chat.id);
  e.nombre = m.from ? [m.from.first_name, m.from.last_name].filter(Boolean).join(' ') : '';
  e.texto = m.text.trim().slice(0, 200);
} else {
  // Fotos, stickers, ediciones, etc.: no se procesan.
  e.ignorar = true;
  e.chat_id = String((u.message && u.message.chat && u.message.chat.id) || '');
  e.usuario_id = e.chat_id;
}

e.clave = `${e.canal}:${e.usuario_id}`;
return [{ json: { ...e, cfg } }];

// 🧠 Motor de citas: decide qué responder según el paso en que va cada
// persona. No depende del canal. Devuelve una "accion":
//   responder | disponibilidad | crear | listar | cancelar | humano
// El estado de cada conversación se guarda en los datos estáticos del
// workflow (persisten entre ejecuciones de producción).
const e = $input.first().json;
const cfg = e.cfg;
const OFF_MS = -5 * 60 * 60000; // Bogotá: UTC-5 todo el año (sin horario de verano)
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];

const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const etiquetaFecha = (f) => {
  const d = new Date(f + 'T12:00:00Z');
  return `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} ${MESES[d.getUTCMonth()]}`;
};
const sumarMin = (hhmm, min) => {
  const [h, m] = hhmm.split(':').map(Number);
  const t = h * 60 + m + min;
  return `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`;
};

const sd = $getWorkflowStaticData('global');
sd.sesiones = sd.sesiones || {};
const ahora = Date.now();
// Limpieza: sesiones sin actividad en 24 h.
for (const k of Object.keys(sd.sesiones)) {
  if (ahora - (sd.sesiones[k].t || 0) > 24 * 3600e3) delete sd.sesiones[k];
}

const base = { canal: e.canal, chat_id: e.chat_id, clave: e.clave, cfg };
if (e.ignorar || !e.chat_id) return [{ json: { ...base, accion: 'responder', mensaje: null } }];

let s = sd.sesiones[e.clave];
if (!s || ahora - (s.t || 0) > 2 * 3600e3) s = { paso: 'menu' }; // 2 h sin actividad: empieza de nuevo
s.t = ahora;
const guardar = () => { sd.sesiones[e.clave] = s; };
const salida = (accion, extra = {}) => { guardar(); return [{ json: { ...base, accion, ...extra } }]; };
const resp = (texto, botones = []) => salida('responder', { mensaje: { texto, botones } });
const filaMenu = [{ t: '🏠 Menú principal', d: 'menu:inicio' }];

const servicioPorId = (id) => cfg.servicios.find((x) => x.id === id);

// Días (desde hoy) que todavía tienen horario de atención para el servicio.
const diasDisponibles = (min) => {
  const lista = [];
  const limite = ahora + cfg.anticipacion_min * 60000;
  for (let i = 0; i <= cfg.dias_adelante; i++) {
    const f = new Date(ahora + OFF_MS + i * 86400e3).toISOString().slice(0, 10);
    const bloques = cfg.horario[new Date(f + 'T12:00:00Z').getUTCDay()] || [];
    if (!bloques.length) continue;
    const ultimoFin = Date.parse(`${f}T${bloques[bloques.length - 1][1]}:00${cfg.offset}`);
    if (ultimoFin - min * 60000 >= limite) lista.push(f);
  }
  return lista;
};

const menu = (prefijo = '') => {
  s = { paso: 'menu', t: ahora };
  return resp(
    `${prefijo}🦷 <b>${esc(cfg.negocio)}</b>\n\n¡Hola! Soy el asistente virtual. ¿Qué quieres hacer?\n\n<i>Este es un negocio ficticio para demostrar una automatización con n8n.</i>`,
    [
      [{ t: '📅 Agendar cita', d: 'menu:agendar' }],
      [{ t: '🗓️ Mis citas', d: 'menu:mis' }],
      [{ t: '📍 Horarios y ubicación', d: 'menu:info' }],
      [{ t: '👤 Hablar con una persona', d: 'menu:humano' }],
    ],
  );
};

const resumen = () => {
  s.paso = 'confirmar';
  const srv = servicioPorId(s.servicio);
  return resp(
    `📋 <b>Revisa tu cita</b>\n\n• Servicio: ${esc(srv.nombre)} (${srv.min} min)\n• Fecha: ${etiquetaFecha(s.fecha)}\n• Hora: ${s.hora}\n• A nombre de: ${esc(s.nombre)}\n\n¿La confirmamos?`,
    [[{ t: '✅ Confirmar', d: 'confirmar:si' }, { t: '❌ Cancelar', d: 'confirmar:no' }]],
  );
};

const txt = (e.texto || '').toLowerCase();
const b = e.boton || '';

// Volver al menú en cualquier momento.
if (b === 'menu:inicio' || ['/start', 'hola', 'menu', 'menú', 'inicio', 'buenas', 'buenos días', 'buenas tardes'].includes(txt)) {
  return menu();
}

if (b === 'menu:agendar') {
  s = { paso: 'servicio', t: ahora };
  return resp('¿Qué servicio necesitas?', [
    ...cfg.servicios.map((x) => [{ t: `${x.nombre} · ${x.min} min`, d: `srv:${x.id}` }]),
    filaMenu,
  ]);
}

if (b.startsWith('srv:')) {
  const srv = servicioPorId(b.slice(4));
  if (!srv) return menu();
  s = { paso: 'dia', servicio: srv.id, t: ahora };
  const dias = diasDisponibles(srv.min);
  if (!dias.length) return resp('No hay días disponibles en este momento. 😕', [filaMenu]);
  const filas = [];
  for (let i = 0; i < dias.length; i += 2) {
    filas.push(dias.slice(i, i + 2).map((f) => ({ t: etiquetaFecha(f), d: `dia:${f}` })));
  }
  return resp(`<b>${esc(srv.nombre)}</b> (${srv.min} min).\n¿Qué día prefieres?`, [...filas, filaMenu]);
}

if (b.startsWith('dia:')) {
  const f = b.slice(4);
  const srv = servicioPorId(s.servicio);
  if (!srv || !diasDisponibles(srv.min).includes(f)) return menu('Esa opción ya no está disponible.\n\n');
  s.fecha = f;
  s.paso = 'hora';
  return salida('disponibilidad', { fecha: f, servicio: srv });
}

if (b.startsWith('hora:')) {
  const h = b.slice(5);
  if (s.paso !== 'hora' || !(s.horas || []).includes(h)) return menu('Ese horario ya no está disponible.\n\n');
  s.hora = h;
  s.paso = 'nombre';
  const botones = e.nombre ? [[{ t: `Usar «${e.nombre.slice(0, 40)}»`, d: 'nombre:perfil' }], filaMenu] : [filaMenu];
  return resp('✍️ ¿A nombre de quién agendamos la cita?\nEscribe nombre y apellido.', botones);
}

if (b === 'nombre:perfil' && s.paso === 'nombre' && e.nombre) {
  s.nombre = e.nombre.slice(0, 60);
  return resumen();
}

if (s.paso === 'nombre' && e.texto) {
  const n = e.texto.replace(/\s+/g, ' ').trim();
  if (n.length < 3 || n.length > 60 || !/^[\p{L} .'-]+$/u.test(n)) {
    return resp('Por favor escribe solo nombre y apellido (entre 3 y 60 letras).', [filaMenu]);
  }
  s.nombre = n;
  return resumen();
}

if (b === 'confirmar:si' && s.paso === 'confirmar') {
  const srv = servicioPorId(s.servicio);
  const fin = sumarMin(s.hora, srv.min);
  const idCita = 'CS-' + ahora.toString(36).toUpperCase();
  const registro = new Date(ahora + OFF_MS).toISOString().slice(0, 16).replace('T', ' ');
  const cita = { id_cita: idCita, servicio: srv.nombre, min: srv.min, fecha: s.fecha, hora: s.hora, fin, nombre: s.nombre };
  s = { paso: 'menu', t: ahora };
  return salida('crear', {
    cita,
    evento: {
      summary: `${srv.nombre} · ${cita.nombre}`,
      description: `Cita ${idCita} agendada por el bot DEMO (canal: ${e.canal}).\nNegocio ficticio de demostración.`,
      start: { dateTime: `${cita.fecha}T${cita.hora}:00${cfg.offset}`, timeZone: cfg.zona },
      end: { dateTime: `${cita.fecha}T${fin}:00${cfg.offset}`, timeZone: cfg.zona },
      extendedProperties: { private: { usuario: e.clave, canal: e.canal, id_cita: idCita } },
    },
    fila: [idCita, registro, e.canal, e.usuario_id, cita.nombre, srv.nombre, cita.fecha, cita.hora, fin, 'agendada'],
    aviso: `🦷 Nueva cita (DEMO)\n${srv.nombre} · ${etiquetaFecha(cita.fecha)} ${cita.hora}\nA nombre de: ${cita.nombre}\nCanal: ${e.canal} · ${idCita}`,
  });
}

if (b === 'confirmar:no') return menu('❌ Listo, no agendamos nada.\n\n');

if (b === 'menu:mis') {
  return salida('listar', { desde: new Date(ahora).toISOString() });
}

if (b.startsWith('cancelar:')) {
  const id = b.slice(9);
  const cita = (s.citas || []).find((x) => x.id === id);
  if (!cita) return menu('No encontré esa cita. Revisa de nuevo en «Mis citas».\n\n');
  s.citas = s.citas.filter((x) => x.id !== id);
  const registro = new Date(ahora + OFF_MS).toISOString().slice(0, 16).replace('T', ' ');
  return salida('cancelar', {
    evento_id: id,
    cita,
    fila: [cita.id_cita || '', registro, e.canal, e.usuario_id, cita.nombre || '', cita.servicio, cita.fecha, cita.hora, cita.fin || '', 'cancelada', id],
    aviso: `🦷 Cita cancelada (DEMO)\n${cita.servicio} · ${etiquetaFecha(cita.fecha)} ${cita.hora}\nCanal: ${e.canal}`,
  });
}

if (b === 'menu:info') {
  const nombresDia = (d) => ({ 1: 'Lunes', 2: 'Martes', 3: 'Miércoles', 4: 'Jueves', 5: 'Viernes', 6: 'Sábado', 0: 'Domingo' })[d];
  const lineas = Object.keys(cfg.horario).map((d) => `• ${nombresDia(Number(d))}: ${cfg.horario[d].map((x) => x.join('–')).join(' y ')}`);
  return resp(`📍 <b>${esc(cfg.negocio)}</b>\n${esc(cfg.direccion)}\n\n🕒 <b>Horario</b>\n${lineas.join('\n')}`, [[{ t: '📅 Agendar cita', d: 'menu:agendar' }], filaMenu]);
}

if (b === 'menu:humano') {
  return salida('humano', {
    mensaje: { texto: '👤 Listo, avisé a una persona del equipo. Te escribirán por este chat en horario de atención.\n\n<i>(En esta demo, el aviso le llega al creador del bot.)</i>', botones: [filaMenu] },
    aviso: `👤 Alguien pide hablar con una persona (DEMO)\nNombre: ${e.nombre || 'sin nombre'}\nCanal: ${e.canal} · chat ${e.chat_id}`,
  });
}

// Cualquier otra cosa: si está a mitad de un proceso, pedir que use los botones.
if (s.paso !== 'menu') {
  return resp('Toca una de las opciones de arriba 👆 o vuelve al menú.', [filaMenu]);
}
return menu();

// Calcula los turnos libres del día elegido a partir de la respuesta
// "freeBusy" de Google Calendar y del horario de atención.
const m = $('Motor').first().json;
const cfg = m.cfg;
const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.sesiones = sd.sesiones || {};
const s = sd.sesiones[m.clave] || { paso: 'menu' };
const OFF_MS = -5 * 60 * 60000;
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const etiqueta = (f) => { const d = new Date(f + 'T12:00:00Z'); return `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} ${MESES[d.getUTCMonth()]}`; };
const filaMenu = [{ t: '🏠 Menú principal', d: 'menu:inicio' }];
const salir = (texto, botones) => [{ json: { ...m, mensaje: { texto, botones } } }];

const cal = r && r.calendars && r.calendars[cfg.calendar_id];
if (!cal || cal.errors) {
  return salir('😕 No pude consultar la agenda en este momento. Intenta de nuevo en unos minutos.', [filaMenu]);
}

const ocupado = (cal.busy || []).map((x) => [Date.parse(x.start), Date.parse(x.end)]);
const dur = m.servicio.min * 60000;
const fecha = m.fecha;
const bloques = cfg.horario[new Date(fecha + 'T12:00:00Z').getUTCDay()] || [];
const limite = Date.now() + cfg.anticipacion_min * 60000;
const libres = [];
for (const [a, z] of bloques) {
  let t = Date.parse(`${fecha}T${a}:00${cfg.offset}`);
  const fin = Date.parse(`${fecha}T${z}:00${cfg.offset}`);
  while (t + dur <= fin) {
    if (t >= limite && !ocupado.some(([ini, f]) => t < f && t + dur > ini)) libres.push(t);
    t += cfg.paso_min * 60000;
  }
}
const horas = libres.slice(0, 16).map((t) => new Date(t + OFF_MS).toISOString().slice(11, 16));

const otroDia = [{ t: '⬅️ Elegir otro día', d: `srv:${m.servicio.id}` }];
if (!horas.length) {
  return salir(`😕 No quedan turnos libres el ${etiqueta(fecha)} para ${m.servicio.nombre}.`, [otroDia, filaMenu]);
}

s.horas = horas;
s.paso = 'hora';
s.t = Date.now();
sd.sesiones[m.clave] = s;

const filas = [];
for (let i = 0; i < horas.length; i += 4) {
  filas.push(horas.slice(i, i + 4).map((h) => ({ t: h, d: `hora:${h}` })));
}
return salir(
  `🕒 Turnos libres el <b>${etiqueta(fecha)}</b> para ${m.servicio.nombre} (${m.servicio.min} min):`,
  [...filas, otroDia, filaMenu],
);

// Mensaje final después de intentar crear el evento en Google Calendar.
const m = $('Motor').first().json;
const ev = $('Calendar: crear evento').first().json;
const filaMenu = [{ t: '🏠 Menú principal', d: 'menu:inicio' }];
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const d = new Date(m.cita.fecha + 'T12:00:00Z');
const fecha = `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} ${MESES[d.getUTCMonth()]}`;
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (!ev || !ev.id) {
  return [{ json: { ...m, mensaje: { texto: '😕 No pude guardar la cita en la agenda. Intenta de nuevo en unos minutos.', botones: [filaMenu] } } }];
}
return [{
  json: {
    ...m,
    mensaje: {
      texto: `✅ <b>¡Cita agendada!</b>\n\n• ${esc(m.cita.servicio)}\n• ${fecha}, ${m.cita.hora} – ${m.cita.fin}\n• A nombre de: ${esc(m.cita.nombre)}\n• Código: <code>${m.cita.id_cita}</code>\n\nPuedes verla o cancelarla en «Mis citas».`,
      botones: [[{ t: '🗓️ Mis citas', d: 'menu:mis' }], filaMenu],
    },
  },
}];

// Lista las próximas citas de esta persona (filtradas en Google Calendar
// por la propiedad privada "usuario") y ofrece cancelarlas.
const m = $('Motor').first().json;
const r = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.sesiones = sd.sesiones || {};
const s = sd.sesiones[m.clave] || { paso: 'menu' };
const OFF_MS = -5 * 60 * 60000;
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const filaMenu = [{ t: '🏠 Menú principal', d: 'menu:inicio' }];
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const salir = (texto, botones) => [{ json: { ...m, mensaje: { texto, botones } } }];

if (!r || r.error || !Array.isArray(r.items)) {
  return salir('😕 No pude consultar tus citas en este momento. Intenta de nuevo en unos minutos.', [filaMenu]);
}

const citas = r.items.filter((x) => x.start && x.start.dateTime).map((x) => {
  const ini = new Date(Date.parse(x.start.dateTime) + OFF_MS).toISOString();
  const fin = new Date(Date.parse(x.end.dateTime) + OFF_MS).toISOString();
  const [servicio, nombre] = String(x.summary || '').split(' · ');
  const p = (x.extendedProperties && x.extendedProperties.private) || {};
  return { id: x.id, id_cita: p.id_cita || '', servicio: servicio || 'Cita', nombre: nombre || '', fecha: ini.slice(0, 10), hora: ini.slice(11, 16), fin: fin.slice(11, 16) };
});

s.citas = citas;
s.paso = 'menu';
s.t = Date.now();
sd.sesiones[m.clave] = s;

if (!citas.length) {
  return salir('No tienes citas próximas. ¿Agendamos una?', [[{ t: '📅 Agendar cita', d: 'menu:agendar' }], filaMenu]);
}
const etiqueta = (f) => { const d = new Date(f + 'T12:00:00Z'); return `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} ${MESES[d.getUTCMonth()]}`; };
const lineas = citas.map((c) => `• ${esc(c.servicio)}: ${etiqueta(c.fecha)}, ${c.hora}`);
return salir(
  `🗓️ <b>Tus próximas citas</b>\n\n${lineas.join('\n')}`,
  [...citas.map((c) => [{ t: `❌ Cancelar ${etiqueta(c.fecha)} ${c.hora}`, d: `cancelar:${c.id}` }]), filaMenu],
);

// Mensaje después de intentar borrar el evento en Google Calendar.
// Google responde vacío (204) si salió bien; con error, n8n deja "error".
const m = $('Motor').first().json;
const r = $('Calendar: cancelar evento').first().json;
const filaMenu = [{ t: '🏠 Menú principal', d: 'menu:inicio' }];
const ok = !(r && r.error);
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
const d = new Date(m.cita.fecha + 'T12:00:00Z');
const fecha = `${DIAS[d.getUTCDay()]} ${d.getUTCDate()} ${MESES[d.getUTCMonth()]}`;
return [{
  json: {
    ...m,
    mensaje: ok
      ? { texto: `🗑️ Cita cancelada: ${m.cita.servicio}, ${fecha} ${m.cita.hora}.\nEse horario quedó libre para otra persona.`, botones: [[{ t: '📅 Agendar otra cita', d: 'menu:agendar' }], filaMenu] }
      : { texto: '😕 No pude cancelar la cita en este momento. Intenta de nuevo en unos minutos.', botones: [[{ t: '🗓️ Mis citas', d: 'menu:mis' }], filaMenu] },
  },
}];

// Convierte el mensaje común { texto, botones } al formato de Telegram.
// La respuesta se devuelve en la misma respuesta HTTP del webhook (método
// "sendMessage"), así el token del bot no tiene que estar en el workflow.
const actual = $input.first().json;
const d = actual.mensaje !== undefined ? actual : $('Motor').first().json;

if (!d.mensaje || d.canal !== 'telegram') {
  return [{ json: { respuesta: {} } }];
}
const respuesta = {
  method: 'sendMessage',
  chat_id: d.chat_id,
  text: d.mensaje.texto,
  parse_mode: 'HTML',
  disable_web_page_preview: true,
};
const teclado = (d.mensaje.botones || []).map((fila) => fila.map((x) => ({ text: x.t, callback_data: x.d })));
if (teclado.length) respuesta.reply_markup = { inline_keyboard: teclado };
return [{ json: { respuesta } }];
